import os,sys,json,hashlib; root,out=sys.argv[1],sys.argv[2]; rows=[]
for d,_,fs in os.walk(root):
    for f in fs:
        p=os.path.join(d,f); st=os.stat(p); rows.append([os.path.relpath(p,root).replace("\\","/"),st.st_size,st.st_mtime_ns])
rows.sort(); body=json.dumps(rows); open(out,"w",encoding="utf-8").write(body); print(len(rows),"files; sha256",hashlib.sha256(body.encode()).hexdigest())

